#[test]
fn c02_manifest_positive_and_empty() {
    let m = Manifest {
        whole_sha256: Digest([0; 32]),
        bytes: CHUNK_BYTES + 3,
        chunks: vec![
            ManifestChunk {
                sha256: Digest([1; 32]),
                bytes: CHUNK_BYTES,
            },
            ManifestChunk {
                sha256: Digest([2; 32]),
                bytes: 3,
            },
        ],
    };
    assert_eq!(m.validate_shape(), Ok(()));
    assert_eq!(
        Manifest {
            bytes: 0,
            chunks: vec![],
            ..m
        }
        .validate_shape(),
        Ok(())
    );
}
#[test]
fn c02_manifest_bad_sum_shape_bounds() {
    for sizes in [vec![1, 2], vec![0], vec![CHUNK_BYTES + 1], vec![]] {
        let m = Manifest {
            whole_sha256: Digest([0; 32]),
            bytes: 3,
            chunks: sizes
                .into_iter()
                .map(|bytes| ManifestChunk {
                    sha256: Digest([1; 32]),
                    bytes,
                })
                .collect(),
        };
        assert_eq!(m.validate_shape(), Err(DomainError::InvalidManifest));
    }
}
#[test]
fn c02_upload_proof_exact_actor_target_epoch_expiry() {
    let p = AclUploadProof {
        actor: actor(7),
        space: space(9),
        target: NodeId::new(11).unwrap(),
        scope: DedupScope::GlobalRegular,
        sha256: Digest([1; 32]),
        acl_generation: Generation(4),
        expires_at_micros: 100,
    };
    assert!(p.matches(p, 99));
    assert!(!p.matches(p, 100));
    assert!(!p.matches(
        AclUploadProof {
            actor: actor(8),
            ..p
        },
        99
    ));
    assert!(!p.matches(
        AclUploadProof {
            target: NodeId::new(12).unwrap(),
            ..p
        },
        99
    ));
    assert!(!p.matches(
        AclUploadProof {
            acl_generation: Generation(5),
            ..p
        },
        99
    ));
    assert!(!p.matches(
        AclUploadProof {
            scope: DedupScope::Protected(space(9)),
            ..p
        },
        99
    ));
}
#[test]
fn c02_repeat_attach_detach_shared_count() {
    let old = ReferenceState {
        revision: Generation(1),
        attached: false,
        shared_count: 4,
        held: false,
    };
    let next = ReferenceState {
        revision: Generation(2),
        attached: true,
        shared_count: 5,
        held: false,
    };
    assert_eq!(
        old.plan(Generation(1), ReferenceIntent::Attach),
        Ok(ReferenceDecision::Replace(next))
    );
    assert_eq!(
        next.plan(Generation(2), ReferenceIntent::Attach),
        Ok(ReferenceDecision::NoChange)
    );
    assert_eq!(
        next.plan(Generation(1), ReferenceIntent::Detach),
        Err(ContractError::StaleReference)
    );
    let detached = ReferenceState {
        revision: Generation(3),
        attached: false,
        shared_count: 4,
        held: false,
    };
    assert_eq!(
        next.plan(Generation(2), ReferenceIntent::Detach),
        Ok(ReferenceDecision::Replace(detached))
    );
    assert_eq!(
        detached.plan(Generation(3), ReferenceIntent::Detach),
        Ok(ReferenceDecision::NoChange)
    );
}
#[test]
fn c02_hold_and_underflow_preserve_reference() {
    let held = ReferenceState {
        revision: Generation(1),
        attached: true,
        shared_count: 1,
        held: true,
    };
    assert_eq!(
        held.plan(Generation(1), ReferenceIntent::Detach),
        Err(ContractError::Held)
    );
    assert_eq!(held.shared_count, 1);
    assert_eq!(
        (ReferenceState {
            held: false,
            shared_count: 0,
            ..held
        })
        .plan(Generation(1), ReferenceIntent::Detach),
        Err(ContractError::Arithmetic)
    );
}
#[test]
fn c02_reclamation_requires_all_fences() {
    let f = ReclamationFacts {
        referenced: false,
        held: false,
        retained_until_micros: None,
        queue_verdict_observed: true,
        metadata_delete_committed: true,
        row_absent_under_chunk_lock: true,
    };
    assert!(f.may_remove_bytes(100));
    for denied in [
        ReclamationFacts {
            referenced: true,
            ..f
        },
        ReclamationFacts { held: true, ..f },
        ReclamationFacts {
            retained_until_micros: Some(101),
            ..f
        },
        ReclamationFacts {
            queue_verdict_observed: false,
            ..f
        },
        ReclamationFacts {
            metadata_delete_committed: false,
            ..f
        },
        ReclamationFacts {
            row_absent_under_chunk_lock: false,
            ..f
        },
    ] {
        assert!(!denied.may_remove_bytes(100));
    }
}
#[test]
fn c03_publish_happy_and_exact_replay() {
    assert_eq!(
        publish().plan(facts(), key(), receipt()),
        Ok(PublicationDecision::AtomicPublish(publication()))
    );
    let accepted = RecordingFacts {
        state: RecordingState::Ready,
        accepted: Some(publication()),
        ..facts()
    };
    assert_eq!(
        publish().plan(accepted, key(), receipt()),
        Ok(PublicationDecision::AlreadyAccepted(publication()))
    );
    let changed = PublishRecording {
        publication: Publication {
            version: VersionId::new(13).unwrap(),
            ..publication()
        },
        ..publish()
    };
    assert_eq!(
        changed.plan(accepted, key(), receipt()),
        Err(ContractError::ConflictingReplay)
    );
}
#[test]
fn c03_stale_capture_participant_revocation_denied() {
    assert_eq!(
        publish().plan(
            RecordingFacts {
                capture_generation: Generation(5),
                ..facts()
            },
            key(),
            receipt()
        ),
        Err(ContractError::StaleGeneration)
    );
    assert_eq!(
        publish().plan(
            RecordingFacts {
                participant_generation: Generation(7),
                ..facts()
            },
            key(),
            receipt()
        ),
        Err(ContractError::StaleGeneration)
    );
    assert_eq!(
        publish().plan(
            facts(),
            AuthorityKey {
                generation: Generation(4),
                ..key()
            },
            receipt()
        ),
        Err(ContractError::StaleAuthority)
    );
}
#[test]
fn c03_wrong_owner_meeting_scope_verification_denied() {
    assert_eq!(
        publish().plan(
            RecordingFacts {
                owner: actor(8),
                ..facts()
            },
            key(),
            receipt()
        ),
        Err(ContractError::ActorMismatch)
    );
    assert_eq!(
        publish().plan(
            RecordingFacts {
                meeting: MeetingId::new(99).unwrap(),
                ..facts()
            },
            key(),
            receipt()
        ),
        Err(ContractError::ScopeMismatch)
    );
    assert_eq!(
        publish().plan(
            RecordingFacts {
                space: space(99),
                ..facts()
            },
            key(),
            receipt()
        ),
        Err(ContractError::ScopeMismatch)
    );
    assert_eq!(
        publish().plan(
            facts(),
            key(),
            VerifiedContentReceipt {
                manifest_digest: Digest([8; 32]),
                ..receipt()
            }
        ),
        Err(ContractError::UnverifiedContent)
    );
}
#[test]
fn c03_late_callback_terminal_state_denied() {
    for state in [
        RecordingState::Requested,
        RecordingState::Active,
        RecordingState::Stopping,
        RecordingState::Failed,
    ] {
        assert_eq!(
            publish().plan(RecordingFacts { state, ..facts() }, key(), receipt()),
            Err(ContractError::InvalidState)
        );
    }
}
#[test]
fn c03_unknown_response_and_feature_off_keep_accepted_work() {
    assert_eq!(
        staging_disposition(RecordingState::Ready, false, true),
        StagingDisposition::Keep
    );
    assert_eq!(
        staging_disposition(RecordingState::Ready, true, false),
        StagingDisposition::RemoveAfterAcceptedCommit
    );
    assert_eq!(
        staging_disposition(RecordingState::PendingIngest, false, true),
        StagingDisposition::Keep
    );
    assert_eq!(
        staging_disposition(RecordingState::Failed, false, false),
        StagingDisposition::Keep
    );
    assert_eq!(
        staging_disposition(RecordingState::Failed, false, true),
        StagingDisposition::RemoveAfterDiagnosticGrace
    );
    // No feature-enable input exists: disabling new intent must not cancel accepted drains.
}
